#include "chemistry.h"
#include <errno.h>
#include <stdarg.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>

void *resize(void *pointer, size_t size) {
    void *result = realloc(pointer, size ? size : 1);
    if (!result) {
        fputs("allocation failed\n", stderr);
        exit(EXIT_FAILURE);
    }
    return result;
}
void *allocate(size_t size) { return resize(NULL, size); }
char *copy_text(const char *value) {
    char *result = allocate(strlen(value) + 1);
    strcpy(result, value);
    return result;
}
static char *format_arguments(const char *format, va_list args) {
    va_list copy;
    va_copy(copy, args);
    int length = vsnprintf(NULL, 0, format, copy);
    va_end(copy);
    if (length < 0)
        exit(EXIT_FAILURE);
    char *result = allocate((size_t)length + 1);
    vsnprintf(result, (size_t)length + 1, format, args);
    return result;
}
char *format_text(const char *format, ...) {
    va_list args;
    va_start(args, format);
    char *result = format_arguments(format, args);
    va_end(args);
    return result;
}
void text_add(Text *text, const char *part) {
    size_t length = strlen(part), needed = text->count + length + 1;
    if (needed > text->capacity) {
        size_t capacity = text->capacity ? 2 * text->capacity : 128;
        while (capacity < needed)
            capacity *= 2;
        text->data = resize(text->data, capacity);
        text->capacity = capacity;
    }
    memcpy(text->data + text->count, part, length + 1);
    text->count += length;
}
void text_format(Text *text, const char *format, ...) {
    va_list args;
    va_start(args, format);
    char *part = format_arguments(format, args);
    va_end(args);
    text_add(text, part);
    free(part);
}
char *text_take(Text *text) {
    char *result = text->data ? text->data : copy_text("");
    *text = (Text){0};
    return result;
}
void lines_add(Lines *lines, char *value) {
    if (lines->count == lines->capacity) {
        lines->capacity = lines->capacity ? 2 * lines->capacity : 64;
        lines->items = resize(lines->items, lines->capacity * sizeof(char *));
    }
    lines->items[lines->count++] = value;
}
void line(Lines *lines, const char *format, ...) {
    va_list args;
    va_start(args, format);
    lines_add(lines, format_arguments(format, args));
    va_end(args);
}
void lines_take(Lines *out, Lines input) {
    for (size_t i = 0; i < input.count; ++i)
        lines_add(out, input.items[i]);
    free(input.items);
}
void lines_free(Lines *lines) {
    for (size_t i = 0; i < lines->count; ++i)
        free(lines->items[i]);
    free(lines->items);
    *lines = (Lines){0};
}
Words split(const char *text, char separator) {
    Words result = {.storage = copy_text(text)};
    char *part = result.storage;
    for (;;) {
        result.items = resize(result.items, (result.count + 1) * sizeof(char *));
        result.items[result.count++] = part;
        char *next = strchr(part, separator);
        if (!next)
            break;
        *next = 0;
        part = next + 1;
    }
    return result;
}
void words_free(Words *words) {
    free(words->items);
    free(words->storage);
}
static FILE *open_file(const char *path, const char *mode) {
    FILE *file = fopen(path, mode);
    if (!file) {
        perror(path);
        exit(EXIT_FAILURE);
    }
    return file;
}
Lines read_lines(const char *path) {
    Lines result = {0};
    FILE *file = open_file(path, "r");
    for (;;) {
        Text text = {0};
        int c;
        while ((c = fgetc(file)) != EOF && c != '\n') {
            char part[2] = {(char)c, 0};
            text_add(&text, part);
        }
        if (c == EOF && !text.count) {
            free(text.data);
            break;
        }
        lines_add(&result, text_take(&text));
    }
    fclose(file);
    return result;
}
void write_lines(const char *name, const Lines *lines) {
    char *path = format_text("output/%s", name);
    FILE *file = open_file(path, "w");
    free(path);
    for (size_t i = 0; i < lines->count; ++i)
        fprintf(file, "%s\n", lines->items[i]);
    fclose(file);
}
bool ignored(const char *text) { return !*text || *text == '#'; }
void paragraph_add(Paragraphs *out, Lines paragraph) {
    if (out->count == out->capacity) {
        out->capacity = out->capacity ? 2 * out->capacity : 8;
        out->items = resize(out->items, out->capacity * sizeof(Lines));
    }
    out->items[out->count++] = paragraph;
}
void paragraphs_free(Paragraphs *paragraphs) {
    for (size_t i = 0; i < paragraphs->count; ++i)
        lines_free(&paragraphs->items[i]);
    free(paragraphs->items);
}
void write_paragraphs(const char *name, const Paragraphs *paragraphs) {
    Lines out = {0};
    for (size_t i = 0; i < paragraphs->count; ++i) {
        Lines paragraph = paragraphs->items[i];
        if (!paragraph.count)
            continue;
        if (out.count)
            line(&out, "");
        for (size_t j = 0; j < paragraph.count; ++j)
            line(&out, "%s", paragraph.items[j]);
    }
    write_lines(name, &out);
    lines_free(&out);
}
static bool valid_name(const char *text) {
    size_t length = strlen(text);
    if (length < 1 || length > 32)
        return false;
    for (; *text; ++text)
        if (!((*text >= 'A' && *text <= 'Z') || (*text >= 'a' && *text <= 'z') ||
              (*text >= '0' && *text <= '9') || *text == '_' || *text == '-'))
            return false;
    return true;
}
static bool analyze(Molecule *m, const Elements *elements, ParseError *error) {
    detect_rings(m);
    for (int e = 0; e < m->bond_count; ++e) {
        Bond *b = &m->bonds[e];
        b->type = symbol_type(b->symbol);
        if (!b->type)
            b->type = b->ring && m->atoms[b->a].aromatic && m->atoms[b->b].aromatic ? 4 : 1;
    }
    if (!kekulize(m, elements, error))
        return false;
    for (int i = 0; i < m->atom_count; ++i) {
        Atom *a = &m->atoms[i];
        if (a->bracket) {
            const Element *element = &elements->items[a->element];
            if (atom_multiplicity(m, i) + a->hydrogens >
                element->valences[element->valence_count - 1] + abs(a->charge)) {
                *error = (ParseError){"bad valence", a->column};
                return false;
            }
        } else {
            int hydrogens;
            if (!organic_hydrogens(m, i, elements, &hydrogens)) {
                *error = (ParseError){"bad valence", a->column};
                return false;
            }
            a->hydrogens = hydrogens;
        }
    }
    return true;
}
static void properties(Molecule *m, const Elements *elements) {
    int counts[40] = {0}, hydrogens = 0,
        *heavy_degree = allocate((size_t)m->atom_count * sizeof(int));
    bool *triple = allocate((size_t)m->atom_count * sizeof(bool));
    memset(heavy_degree, 0, (size_t)m->atom_count * sizeof(int));
    memset(triple, 0, (size_t)m->atom_count * sizeof(bool));
    int hydrogen = element_index(elements, "H"), carbon = element_index(elements, "C");
    for (int i = 0; i < m->atom_count; ++i) {
        Atom a = m->atoms[i];
        const char *symbol = elements->items[a.element].symbol;
        ++counts[a.element];
        hydrogens += a.hydrogens;
        m->charge += a.charge;
        m->weight += a.mass ? a.mass * 1000 : elements->items[a.element].weight;
        m->heavy += strcmp(symbol, "H") != 0;
        int attached = a.hydrogens;
        for (int j = 0; j < m->adjacent[i].count; ++j) {
            Bond b = m->bonds[m->adjacent[i].items[j]];
            if (m->atoms[bond_other(&b, i)].element == hydrogen)
                ++attached;
            else
                ++heavy_degree[i];
            if (b.multiplicity == 3)
                triple[i] = true;
        }
        if (!strcmp(symbol, "N") || !strcmp(symbol, "O")) {
            ++m->acceptors;
            if (attached)
                ++m->donors;
        }
    }
    counts[hydrogen] += hydrogens;
    m->weight += hydrogens * elements->items[hydrogen].weight;
    IntList order = {0};
    for (int i = 0; i < elements->count; ++i)
        if (counts[i])
            ints_add(&order, i);
    for (int i = 1; i < order.count; ++i) {
        int element = order.items[i], j = i;
        while (j && strcmp(elements->items[order.items[j - 1]].symbol,
                           elements->items[element].symbol) > 0) {
            order.items[j] = order.items[j - 1];
            --j;
        }
        order.items[j] = element;
    }
    IntList hill = {0};
    if (counts[carbon]) {
        ints_add(&hill, carbon);
        if (counts[hydrogen])
            ints_add(&hill, hydrogen);
    }
    for (int i = 0; i < order.count; ++i)
        if (!counts[carbon] || (order.items[i] != carbon && order.items[i] != hydrogen))
            ints_add(&hill, order.items[i]);
    Text formula = {0};
    for (int i = 0; i < hill.count; ++i) {
        int element = hill.items[i];
        text_add(&formula, elements->items[element].symbol);
        if (counts[element] > 1)
            text_format(&formula, "%d", counts[element]);
    }
    m->formula = text_take(&formula);
    ints_free(&order);
    ints_free(&hill);
    for (int e = 0; e < m->bond_count; ++e) {
        Bond b = m->bonds[e];
        if (b.multiplicity == 1 && !b.ring && heavy_degree[b.a] >= 2 && heavy_degree[b.b] >= 2 &&
            !triple[b.a] && !triple[b.b])
            ++m->rotatable;
    }
    int violations = (m->weight > 500000) + (m->donors > 5) + (m->acceptors > 10);
    m->lipinski = violations < 2 ? "pass" : "fail";
    free(heavy_degree);
    free(triple);
}
static char *scaffold(const Molecule *m, const Elements *elements) {
    if (!m->ring_count)
        return copy_text("");
    bool *remaining = allocate((size_t)m->atom_count * sizeof(bool)),
         *keep = allocate((size_t)m->atom_count * sizeof(bool));
    for (int i = 0; i < m->atom_count; ++i)
        remaining[i] = true;
    for (;;) {
        int remove = -1;
        for (int a = 0; a < m->atom_count; ++a) {
            if (!remaining[a] || m->ring_atoms[a])
                continue;
            int degree = 0;
            for (int j = 0; j < m->adjacent[a].count; ++j)
                degree += remaining[bond_other(&m->bonds[m->adjacent[a].items[j]], a)];
            if (degree == 1) {
                remove = a;
                break;
            }
        }
        if (remove < 0)
            break;
        remaining[remove] = false;
    }
    memcpy(keep, remaining, (size_t)m->atom_count * sizeof(bool));
    for (int e = 0; e < m->bond_count; ++e) {
        Bond b = m->bonds[e];
        if (b.multiplicity == 2) {
            if (remaining[b.a])
                keep[b.b] = true;
            if (remaining[b.b])
                keep[b.a] = true;
        }
    }
    Molecule *s = molecule_new();
    int *renumber = allocate((size_t)m->atom_count * sizeof(int));
    for (int i = 0; i < m->atom_count; ++i) {
        renumber[i] = -1;
        if (!keep[i])
            continue;
        Atom atom = m->atoms[i];
        atom.choices = NULL;
        atom.choice_count = 0;
        for (int j = 0; j < m->adjacent[i].count; ++j) {
            Bond b = m->bonds[m->adjacent[i].items[j]];
            if (!keep[bond_other(&b, i)])
                atom.hydrogens += b.multiplicity;
        }
        renumber[i] = s->atom_count;
        molecule_add_atom(s, atom);
    }
    for (int e = 0; e < m->bond_count; ++e) {
        Bond b = m->bonds[e];
        if (keep[b.a] && keep[b.b]) {
            b.a = renumber[b.a];
            b.b = renumber[b.b];
            molecule_add_bond(s, b);
        }
    }
    molecule_build(s);
    canonical_ranks(s, elements);
    char *result = canonical_smiles(s, elements);
    molecule_free(s);
    free(remaining);
    free(keep);
    free(renumber);
    return result;
}
static int ring_relation(const Molecule *m, const IntList *a, const IntList *b) {
    int count = 0, first = -1, second = -1;
    for (int i = 0; i < a->count; ++i)
        if (ints_contains(b, a->items[i])) {
            if (!count)
                first = a->items[i];
            else if (count == 1)
                second = a->items[i];
            ++count;
        }
    if (count == 1)
        return 2;
    if (count == 2 && molecule_bond(m, first, second))
        return 1;
    return count >= 2 ? 3 : -1;
}
static const char *const system_names[] = {"isolated", "fused", "spiro", "bridged"};
typedef struct {
    IntList rings;
    int kind, atoms;
} RingSystem;
typedef struct {
    RingSystem *items;
    int count;
} RingSystems;
static RingSystems ring_systems(const Molecule *m) {
    RingSystems out = {.items = allocate((size_t)m->ring_count * sizeof(RingSystem))};
    bool *seen = allocate((size_t)m->ring_count * sizeof(bool));
    memset(seen, 0, (size_t)m->ring_count * sizeof(bool));
    for (int first = 0; first < m->ring_count; ++first) {
        if (seen[first])
            continue;
        IntList queue = {0};
        ints_add(&queue, first);
        seen[first] = true;
        for (int head = 0; head < queue.count; ++head)
            for (int next = 0; next < m->ring_count; ++next)
                if (!seen[next] &&
                    ring_relation(m, &m->rings[queue.items[head]], &m->rings[next]) >= 0) {
                    seen[next] = true;
                    ints_add(&queue, next);
                }
        ints_sort(&queue);
        bool atoms[300] = {0};
        int atom_count = 0, kind = queue.count == 1 ? 0 : 2;
        for (int i = 0; i < queue.count; ++i) {
            IntList ring = m->rings[queue.items[i]];
            for (int a = 0; a < ring.count; ++a)
                atoms[ring.items[a]] = true;
            for (int j = i + 1; j < queue.count; ++j) {
                int relation = ring_relation(m, &ring, &m->rings[queue.items[j]]);
                if (relation == 3)
                    kind = 3;
                else if (relation == 1 && kind != 3)
                    kind = 1;
            }
        }
        for (int a = 0; a < m->atom_count; ++a)
            atom_count += atoms[a];
        out.items[out.count++] = (RingSystem){queue, kind, atom_count};
    }
    free(seen);
    return out;
}
static bool ring_aromatic(const Molecule *m, const IntList *ring) {
    for (int i = 0; i < ring->count; ++i)
        if (!m->atoms[ring->items[i]].aromatic)
            return false;
    return true;
}
static char *integers(const IntList *values, const char *separator, int offset) {
    Text out = {0};
    for (int i = 0; i < values->count; ++i)
        text_format(&out, "%s%d", i ? separator : "", values->items[i] + offset);
    return text_take(&out);
}
static char *member_names(Molecule *const *molecules, const IntList *indices) {
    Text out = {0};
    for (int i = 0; i < indices->count; ++i) {
        if (i)
            text_add(&out, ",");
        text_add(&out, molecules[indices->items[i]]->name);
    }
    return text_take(&out);
}
typedef struct {
    const char *key;
    IntList members;
} KeyGroup;
static void group_add(KeyGroup groups[300], int *count, const char *key, int index) {
    for (int i = 0; i < *count; ++i)
        if (strcmp(groups[i].key, key) == 0) {
            ints_add(&groups[i].members, index);
            return;
        }
    groups[*count] = (KeyGroup){.key = key};
    ints_add(&groups[(*count)++].members, index);
}
static Paragraphs canonical_paragraphs(Molecule *const *molecules, int n) {
    KeyGroup canon[300] = {0}, formula[300] = {0}, scaffolds[300] = {0};
    int cc = 0, fc = 0, sc = 0, acyclic = 0;
    for (int i = 0; i < n; ++i) {
        Molecule *m = molecules[i];
        group_add(canon, &cc, m->canonical, i);
        group_add(formula, &fc, m->formula, i);
        if (*m->scaffold)
            group_add(scaffolds, &sc, m->scaffold, i);
        else
            ++acyclic;
    }
    Paragraphs out = {0};
    Lines canonical = {0}, duplicates = {0}, isomers = {0}, scaffold_lines = {0};
    line(&canonical, "CANONICAL molecules=%d unique=%d", n, cc);
    for (int i = 0; i < n; ++i) {
        Molecule *m = molecules[i];
        line(&canonical, "%s %s classes=%d charge=%s%d", m->name, m->canonical, m->classes,
             m->charge > 0 ? "+" : "", m->charge);
    }
    int duplicate_count = 0, duplicate_molecules = 0;
    for (int i = 0; i < cc; ++i)
        if (canon[i].members.count >= 2) {
            ++duplicate_count;
            duplicate_molecules += canon[i].members.count;
        }
    line(&duplicates, "DUPLICATES groups=%d molecules=%d", duplicate_count, duplicate_molecules);
    int serial = 0;
    for (int i = 0; i < cc; ++i)
        if (canon[i].members.count >= 2) {
            char *members = member_names(molecules, &canon[i].members);
            line(&duplicates, "group %d %s members=%s", ++serial, canon[i].key, members);
            free(members);
        }
    Lines isomer_rows = {0};
    for (int i = 0; i < fc; ++i) {
        IntList group = formula[i].members;
        int distinct = 0;
        for (int a = 0; a < group.count; ++a) {
            bool seen = false;
            for (int b = 0; b < a; ++b)
                if (strcmp(molecules[group.items[a]]->canonical,
                           molecules[group.items[b]]->canonical) == 0)
                    seen = true;
            if (!seen)
                ++distinct;
        }
        if (distinct >= 2) {
            char *members = member_names(molecules, &group);
            line(&isomer_rows, "isomer %zu %s forms=%d members=%s", isomer_rows.count + 1,
                 formula[i].key, distinct, members);
            free(members);
        }
    }
    line(&isomers, "ISOMERS groups=%zu", isomer_rows.count);
    lines_take(&isomers, isomer_rows);
    line(&scaffold_lines, "SCAFFOLDS distinct=%d acyclic=%d", sc, acyclic);
    int order[300];
    for (int i = 0; i < sc; ++i)
        order[i] = i;
    for (int i = 1; i < sc; ++i) {
        int current = order[i], j = i;
        while (j) {
            int previous = order[j - 1];
            bool less = scaffolds[current].members.count != scaffolds[previous].members.count
                            ? scaffolds[current].members.count > scaffolds[previous].members.count
                            : strcmp(scaffolds[current].key, scaffolds[previous].key) < 0;
            if (!less)
                break;
            order[j] = previous;
            --j;
        }
        order[j] = current;
    }
    for (int i = 0; i < sc; ++i) {
        KeyGroup group = scaffolds[order[i]];
        char *members = member_names(molecules, &group.members);
        line(&scaffold_lines, "scaffold %d %s count=%d members=%s", i + 1, group.key,
             group.members.count, members);
        free(members);
    }
    paragraph_add(&out, canonical);
    paragraph_add(&out, duplicates);
    paragraph_add(&out, isomers);
    paragraph_add(&out, scaffold_lines);
    for (int i = 0; i < cc; ++i)
        ints_free(&canon[i].members);
    for (int i = 0; i < fc; ++i)
        ints_free(&formula[i].members);
    for (int i = 0; i < sc; ++i)
        ints_free(&scaffolds[i].members);
    return out;
}
static Paragraphs ring_paragraphs(Molecule *const *molecules, int n, const Elements *elements) {
    Paragraphs out = {0};
    int cyclic = 0, total = 0, aromatic = 0, sizes[301] = {0}, kinds[4] = {0};
    int carbon = element_index(elements, "C");
    for (int i = 0; i < n; ++i) {
        Molecule *m = molecules[i];
        if (!m->ring_count)
            continue;
        ++cyclic;
        total += m->ring_count;
        RingSystems systems = ring_systems(m);
        int aromatic_count = 0, ring_atoms = 0, ring_bonds = 0;
        for (int a = 0; a < m->atom_count; ++a)
            ring_atoms += m->ring_atoms[a];
        for (int e = 0; e < m->bond_count; ++e)
            ring_bonds += m->bonds[e].ring;
        for (int r = 0; r < m->ring_count; ++r) {
            ++sizes[m->rings[r].count];
            aromatic_count += ring_aromatic(m, &m->rings[r]);
        }
        aromatic += aromatic_count;
        Lines paragraph = {0};
        line(
            &paragraph,
            "MOLECULE %s atoms=%d bonds=%d rings=%d aromatic=%d systems=%d ring_atoms=%d ring_bonds=%d",
            m->name, m->atom_count, m->bond_count, m->ring_count, aromatic_count, systems.count,
            ring_atoms, ring_bonds);
        for (int r = 0; r < m->ring_count; ++r) {
            IntList ring = m->rings[r];
            int hetero = 0;
            for (int a = 0; a < ring.count; ++a)
                hetero += m->atoms[ring.items[a]].element != carbon;
            char *atoms = integers(&ring, "-", 1);
            line(&paragraph, "ring %d size=%d aromatic=%s hetero=%d atoms=%s", r + 1, ring.count,
                 ring_aromatic(m, &ring) ? "yes" : "no", hetero, atoms);
            free(atoms);
        }
        for (int s = 0; s < systems.count; ++s) {
            RingSystem system = systems.items[s];
            ++kinds[system.kind];
            char *rings = integers(&system.rings, ",", 1);
            line(&paragraph, "system %d kind=%s rings=%s atoms=%d", s + 1,
                 system_names[system.kind], rings, system.atoms);
            free(rings);
            ints_free(&systems.items[s].rings);
        }
        free(systems.items);
        Text double_bonds = {0};
        text_add(&double_bonds, "kekule");
        bool any = false;
        for (int e = 0; e < m->bond_count; ++e) {
            Bond b = m->bonds[e];
            if (b.type == 4 && b.multiplicity == 2) {
                text_format(&double_bonds, " %d=%d", b.a + 1, b.b + 1);
                any = true;
            }
        }
        if (!any)
            text_add(&double_bonds, " -");
        lines_add(&paragraph, text_take(&double_bonds));
        paragraph_add(&out, paragraph);
    }
    Lines summary = {0};
    line(&summary, "SUMMARY molecules=%d cyclic=%d rings=%d aromatic=%d", n, cyclic, total,
         aromatic);
    Text size_line = {0};
    text_add(&size_line, "sizes");
    bool any = false;
    for (int size = 1; size <= 300; ++size)
        if (sizes[size]) {
            text_format(&size_line, " %d=%d", size, sizes[size]);
            any = true;
        }
    if (!any)
        text_add(&size_line, " -");
    lines_add(&summary, text_take(&size_line));
    line(&summary, "systems isolated=%d fused=%d spiro=%d bridged=%d", kinds[0], kinds[1], kinds[2],
         kinds[3]);
    paragraph_add(&out, summary);
    return out;
}
typedef enum {
    QUERY_MATCH,
    QUERY_CONTAINS,
    QUERY_MATRIX,
    QUERY_NEAREST,
    QUERY_WITHIN,
    QUERY_COMPARE,
    QUERY_CLUSTER
} QueryKind;
static const char *const query_names[] = {"MATCH",  "CONTAINS", "MATRIX", "NEAREST",
                                          "WITHIN", "COMPARE",  "CLUSTER"};
typedef struct {
    QueryKind kind;
    Words source;
    char *id, **args;
    size_t argument_count;
    Molecule *pattern;
    Fraction threshold;
    int count;
} Query;
static int molecule_index(Molecule *const *molecules, int count, const char *name) {
    for (int i = 0; i < count; ++i)
        if (strcmp(molecules[i]->name, name) == 0)
            return i;
    return -1;
}
static bool number(const char *text, int low, int high) {
    size_t length = strlen(text);
    if (length < 1 || length > 2 || (length > 1 && text[0] == '0'))
        return false;
    for (const char *p = text; *p; ++p)
        if (!digit(*p))
            return false;
    int value = atoi(text);
    return value >= low && value <= high;
}
static bool parse_threshold(const char *text, Fraction *out) {
    Words a = split(text, '/');
    bool valid = a.count == 2 && number(a.items[0], 0, 99) && number(a.items[1], 1, 99);
    if (valid) {
        int n = atoi(a.items[0]), d = atoi(a.items[1]);
        valid = n <= d;
        if (valid)
            *out = fraction(n, d);
    }
    words_free(&a);
    return valid;
}
static Query *check_query(Words *tokens, char seen[100][33], int *seen_count,
                          Molecule *const *molecules, int n, const Elements *elements,
                          char **reason) {
    int kind = -1;
    for (int i = 0; i < 7; ++i)
        if (strcmp(tokens->items[0], query_names[i]) == 0)
            kind = i;
    if (kind < 0) {
        *reason = copy_text("unknown query");
        return NULL;
    }
    if (tokens->count == 1 || !valid_name(tokens->items[1])) {
        *reason = copy_text("bad id");
        return NULL;
    }
    const char *id = tokens->items[1];
    for (int i = 0; i < *seen_count; ++i)
        if (strcmp(id, seen[i]) == 0) {
            *reason = copy_text("duplicate id");
            return NULL;
        }
    strcpy(seen[(*seen_count)++], id);
    char **args = tokens->items + 2;
    size_t count = tokens->count - 2;
    bool length = kind == QUERY_MATCH || kind == QUERY_CLUSTER ? count == 1
                  : kind == QUERY_MATRIX                       ? count >= 2 && count <= 12
                                                               : count == 2;
    if (!length) {
        *reason = copy_text("bad arguments");
        return NULL;
    }
    Molecule *pattern = NULL;
    Fraction threshold = {0, 1};
    int nearest = 0;
    if (kind == QUERY_MATCH) {
        ParseError error;
        pattern = parse_smiles(args[0], elements, true, &error);
        if (!pattern) {
            *reason = format_text("bad pattern %s at column %d", error.reason, error.column);
            return NULL;
        }
    } else if (kind == QUERY_CLUSTER) {
        if (!parse_threshold(args[0], &threshold)) {
            *reason = copy_text("bad threshold");
            return NULL;
        }
    } else if (kind == QUERY_CONTAINS || kind == QUERY_MATRIX || kind == QUERY_COMPARE) {
        for (size_t i = 0; i < count; ++i)
            if (molecule_index(molecules, n, args[i]) < 0) {
                *reason = format_text("unknown molecule %s", args[i]);
                return NULL;
            }
        for (size_t i = 0; i < count; ++i)
            for (size_t j = 0; j < i; ++j)
                if (strcmp(args[i], args[j]) == 0) {
                    *reason = copy_text("repeated molecule");
                    return NULL;
                }
    } else {
        if (molecule_index(molecules, n, args[0]) < 0) {
            *reason = format_text("unknown molecule %s", args[0]);
            return NULL;
        }
        if (kind == QUERY_NEAREST) {
            if (!number(args[1], 1, 99)) {
                *reason = copy_text("bad count");
                return NULL;
            }
            nearest = atoi(args[1]);
        } else if (!parse_threshold(args[1], &threshold)) {
            *reason = copy_text("bad threshold");
            return NULL;
        }
    }
    Query *query = allocate(sizeof(*query));
    *query = (Query){.kind = (QueryKind)kind,
                     .source = *tokens,
                     .pattern = pattern,
                     .threshold = threshold,
                     .count = nearest,
                     .argument_count = count};
    *tokens = (Words){0};
    query->id = query->source.items[1];
    query->args = query->source.items + 2;
    return query;
}
static Paragraphs substructure_paragraphs(Query *const *queries, int query_count,
                                          Molecule *const *molecules, int n) {
    Paragraphs out = {0};
    int patterns = 0, hits = 0, contains = 0, found = 0;
    for (int qn = 0; qn < query_count; ++qn) {
        Query *q = queries[qn];
        if (q->kind == QUERY_MATCH) {
            ++patterns;
            Lines hit_lines = {0};
            int total = 0, top_count = 0, top = -1;
            for (int i = 0; i < n; ++i) {
                Embeddings result = embeddings(q->pattern, molecules[i]);
                if (result.count) {
                    ++hits;
                    total += result.count;
                    char *mapping = integers(&result.first, ",", 0);
                    line(&hit_lines, "%s count=%d unique=%d map=%s", molecules[i]->name,
                         result.count, result.unique, mapping);
                    free(mapping);
                    if (result.count > top_count) {
                        top = i;
                        top_count = result.count;
                    }
                }
                ints_free(&result.first);
            }
            Lines paragraph = {0};
            line(&paragraph, "MATCH %s %s atoms=%d bonds=%d hits=%zu embeddings=%d", q->id,
                 q->args[0], q->pattern->atom_count, q->pattern->bond_count, hit_lines.count,
                 total);
            lines_take(&paragraph, hit_lines);
            if (top >= 0)
                line(&paragraph, "top %s count=%d", molecules[top]->name, top_count);
            paragraph_add(&out, paragraph);
        } else if (q->kind == QUERY_CONTAINS) {
            ++contains;
            Molecule *x = molecules[molecule_index(molecules, n, q->args[0])],
                     *y = molecules[molecule_index(molecules, n, q->args[1])],
                     *pattern = molecule_pattern(x);
            Embeddings result = embeddings(pattern, y);
            Lines paragraph = {0};
            if (result.count) {
                ++found;
                char *mapping = integers(&result.first, ",", 0);
                line(&paragraph, "CONTAINS %s %s %s result=yes count=%d unique=%d map=%s", q->id,
                     x->name, y->name, result.count, result.unique, mapping);
                free(mapping);
            } else
                line(&paragraph, "CONTAINS %s %s %s result=no", q->id, x->name, y->name);
            ints_free(&result.first);
            molecule_free(pattern);
            paragraph_add(&out, paragraph);
        }
    }
    Lines summary = {0};
    line(&summary, "SUMMARY patterns=%d hits=%d contains=%d found=%d", patterns, hits, contains,
         found);
    paragraph_add(&out, summary);
    return out;
}
static Paragraphs similarity_paragraphs(Query *const *queries, int query_count,
                                        Molecule *const *molecules, int n) {
    Similarity *matrix = allocate((size_t)n * n * sizeof(Similarity));
    for (int i = 0; i < n; ++i)
        for (int j = i; j < n; ++j)
            matrix[i * n + j] = matrix[j * n + i] = similarity(molecules[i], molecules[j]);
    Paragraphs out = {0};
    Lines fingerprints = {0};
    line(&fingerprints, "FINGERPRINTS molecules=%d size=1024 depth=5", n);
    for (int i = 0; i < n; ++i)
        line(&fingerprints, "%s bits=%d paths=%d", molecules[i]->name, molecules[i]->bit_count,
             molecules[i]->paths);
    paragraph_add(&out, fingerprints);
    for (int qn = 0; qn < query_count; ++qn) {
        Query *q = queries[qn];
        Lines paragraph = {0};
        char f[32];
        if (q->kind == QUERY_MATRIX) {
            int indices[12];
            for (size_t i = 0; i < q->argument_count; ++i)
                indices[i] = molecule_index(molecules, n, q->args[i]);
            line(&paragraph, "MATRIX %s size=%zu", q->id, q->argument_count);
            int best_i = 0, best_j = 1;
            for (int i = 0; i < (int)q->argument_count; ++i) {
                Text row = {0};
                text_format(&row, "row %s", q->args[i]);
                for (int j = 0; j < (int)q->argument_count; ++j) {
                    Similarity value = matrix[indices[i] * n + indices[j]];
                    text_format(&row, " %s", fraction_text(value.value, f));
                    if (i < j &&
                        fraction_compare(value.value,
                                         matrix[indices[best_i] * n + indices[best_j]].value) > 0) {
                        best_i = i;
                        best_j = j;
                    }
                }
                lines_add(&paragraph, text_take(&row));
            }
            line(&paragraph, "best %s %s %s", q->args[best_i], q->args[best_j],
                 fraction_text(matrix[indices[best_i] * n + indices[best_j]].value, f));
        } else if (q->kind == QUERY_NEAREST || q->kind == QUERY_WITHIN) {
            int base = molecule_index(molecules, n, q->args[0]);
            IntList order = {0};
            for (int i = 0; i < n; ++i)
                if (i != base)
                    ints_add(&order, i);
            for (int i = 1; i < order.count; ++i) {
                int current = order.items[i], j = i;
                while (j && fraction_compare(matrix[base * n + current].value,
                                             matrix[base * n + order.items[j - 1]].value) > 0) {
                    order.items[j] = order.items[j - 1];
                    --j;
                }
                order.items[j] = current;
            }
            if (q->kind == QUERY_NEAREST) {
                if (order.count > q->count)
                    order.count = q->count;
                line(&paragraph, "NEAREST %s %s count=%d", q->id, q->args[0], order.count);
            } else {
                int count = 0;
                for (int i = 0; i < order.count; ++i)
                    if (fraction_compare(matrix[base * n + order.items[i]].value, q->threshold) >=
                        0)
                        order.items[count++] = order.items[i];
                order.count = count;
                line(&paragraph, "WITHIN %s %s threshold=%s count=%d", q->id, q->args[0],
                     fraction_text(q->threshold, f), order.count);
            }
            for (int i = 0; i < order.count; ++i) {
                int index = order.items[i];
                Similarity value = matrix[base * n + index];
                line(&paragraph, "%d %s %s common=%d", i + 1, molecules[index]->name,
                     fraction_text(value.value, f), value.common);
            }
            ints_free(&order);
        } else if (q->kind == QUERY_COMPARE) {
            int a = molecule_index(molecules, n, q->args[0]),
                b = molecule_index(molecules, n, q->args[1]);
            Similarity value = matrix[a * n + b];
            line(&paragraph,
                 "COMPARE %s %s %s bits=%d,%d common=%d union=%d tanimoto=%s identical=%s", q->id,
                 q->args[0], q->args[1], molecules[a]->bit_count, molecules[b]->bit_count,
                 value.common, value.total, fraction_text(value.value, f),
                 strcmp(molecules[a]->canonical, molecules[b]->canonical) == 0 ? "yes" : "no");
        } else if (q->kind == QUERY_CLUSTER) {
            IntList *neighbors = allocate((size_t)n * sizeof(IntList)),
                    *clusters = allocate((size_t)n * sizeof(IntList));
            memset(neighbors, 0, (size_t)n * sizeof(IntList));
            int *order = allocate((size_t)n * sizeof(int));
            bool *assigned = allocate((size_t)n * sizeof(bool));
            memset(assigned, 0, (size_t)n * sizeof(bool));
            for (int i = 0; i < n; ++i) {
                order[i] = i;
                for (int j = 0; j < n; ++j)
                    if (i != j && fraction_compare(matrix[i * n + j].value, q->threshold) >= 0)
                        ints_add(&neighbors[i], j);
            }
            for (int i = 1; i < n; ++i) {
                int current = order[i], j = i;
                while (j && neighbors[current].count > neighbors[order[j - 1]].count) {
                    order[j] = order[j - 1];
                    --j;
                }
                order[j] = current;
            }
            int cluster_count = 0, singletons = 0;
            for (int i = 0; i < n; ++i) {
                int center = order[i];
                if (assigned[center])
                    continue;
                IntList members = {0};
                ints_add(&members, center);
                assigned[center] = true;
                for (int j = 0; j < neighbors[center].count; ++j) {
                    int neighbor = neighbors[center].items[j];
                    if (!assigned[neighbor]) {
                        ints_add(&members, neighbor);
                        assigned[neighbor] = true;
                    }
                }
                singletons += members.count == 1;
                clusters[cluster_count++] = members;
            }
            line(&paragraph, "CLUSTER %s threshold=%s clusters=%d singletons=%d", q->id,
                 fraction_text(q->threshold, f), cluster_count, singletons);
            int serial = 0;
            for (int i = 0; i < cluster_count; ++i) {
                IntList members = clusters[i];
                if (members.count >= 2) {
                    char *names = member_names(molecules, &members);
                    line(&paragraph, "cluster %d centroid=%s size=%d members=%s", ++serial,
                         molecules[members.items[0]]->name, members.count, names);
                    free(names);
                }
                ints_free(&clusters[i]);
            }
            for (int i = 0; i < n; ++i)
                ints_free(&neighbors[i]);
            free(neighbors);
            free(clusters);
            free(order);
            free(assigned);
        }
        if (paragraph.count)
            paragraph_add(&out, paragraph);
    }
    free(matrix);
    return out;
}
typedef struct {
    char *name;
    int count;
} Cause;
static void cause_add(Cause causes[400], int *count, const char *name) {
    for (int i = 0; i < *count; ++i)
        if (strcmp(causes[i].name, name) == 0) {
            ++causes[i].count;
            return;
        }
    causes[*count] = (Cause){copy_text(name), 1};
    ++*count;
}
static void save_paragraphs(const char *name, Paragraphs paragraphs) {
    write_paragraphs(name, &paragraphs);
    paragraphs_free(&paragraphs);
}
int main(void) {
    Elements elements;
    read_elements(&elements);
    Molecule *molecules[300];
    int molecule_count = 0, molecule_lines = 0, seen_name_count = 0;
    char seen_names[300][33];
    Lines molecule_errors = {0}, query_errors = {0};
    Cause causes[400];
    int cause_count = 0;
    Lines source = read_lines("input/molecules.smi");
    for (size_t i = 0; i < source.count; ++i) {
        if (ignored(source.items[i]))
            continue;
        ++molecule_lines;
        Words tokens = split(source.items[i], ' ');
        if (tokens.count != 2 || !*tokens.items[0] || !valid_name(tokens.items[1])) {
            line(&molecule_errors, "line %zu: bad line", i + 1);
            cause_add(causes, &cause_count, "bad line");
            words_free(&tokens);
            continue;
        }
        const char *name = tokens.items[1];
        bool duplicate = false;
        for (int j = 0; j < seen_name_count; ++j)
            if (strcmp(name, seen_names[j]) == 0)
                duplicate = true;
        if (duplicate) {
            line(&molecule_errors, "line %zu %s: duplicate name", i + 1, name);
            cause_add(causes, &cause_count, "duplicate name");
            words_free(&tokens);
            continue;
        }
        strcpy(seen_names[seen_name_count++], name);
        ParseError error;
        Molecule *m = parse_smiles(tokens.items[0], &elements, false, &error);
        if (m && !analyze(m, &elements, &error)) {
            molecule_free(m);
            m = NULL;
        }
        if (!m) {
            line(&molecule_errors, "line %zu %s: %s at column %d", i + 1, name, error.reason,
                 error.column);
            cause_add(causes, &cause_count, error.reason);
            words_free(&tokens);
            continue;
        }
        m->name = copy_text(name);
        properties(m, &elements);
        canonical_ranks(m, &elements);
        m->canonical = canonical_smiles(m, &elements);
        m->scaffold = scaffold(m, &elements);
        fingerprint(m, &elements);
        molecules[molecule_count++] = m;
        words_free(&tokens);
    }
    lines_free(&source);
    Query *queries[100];
    int query_count = 0, query_lines = 0, seen_id_count = 0;
    char seen_ids[100][33];
    source = read_lines("input/queries.txt");
    for (size_t i = 0; i < source.count; ++i) {
        if (ignored(source.items[i]))
            continue;
        ++query_lines;
        Words tokens = split(source.items[i], ' ');
        char *reason = NULL;
        Query *q = check_query(&tokens, seen_ids, &seen_id_count, molecules, molecule_count,
                               &elements, &reason);
        if (reason) {
            if (strcmp(reason, "unknown query") == 0)
                line(&query_errors, "line %zu: unknown query", i + 1);
            else if (strcmp(reason, "bad id") == 0)
                line(&query_errors, "line %zu %s: bad id", i + 1, tokens.items[0]);
            else
                line(&query_errors, "line %zu %s %s: %s", i + 1, tokens.items[0], tokens.items[1],
                     reason);
            const char *cause = strncmp(reason, "bad pattern ", 12) == 0        ? "bad pattern"
                                : strncmp(reason, "unknown molecule ", 17) == 0 ? "unknown molecule"
                                                                                : reason;
            cause_add(causes, &cause_count, cause);
            free(reason);
        } else
            queries[query_count++] = q;
        words_free(&tokens);
    }
    lines_free(&source);
    Lines property_lines = {0};
    line(&property_lines,
         "name,formula,weight,heavy_atoms,rings,rotatable,donors,acceptors,lipinski");
    for (int i = 0; i < molecule_count; ++i) {
        Molecule *m = molecules[i];
        line(&property_lines, "%s,%s,%d.%03d,%d,%d,%d,%d,%d,%s", m->name, m->formula,
             m->weight / 1000, m->weight % 1000, m->heavy, m->ring_count, m->rotatable, m->donors,
             m->acceptors, m->lipinski);
    }
    Lines mol_errors = {0}, que_errors = {0}, cause_lines = {0};
    line(&mol_errors, "MOLECULES lines=%d valid=%d errors=%zu", molecule_lines, molecule_count,
         molecule_errors.count);
    lines_take(&mol_errors, molecule_errors);
    line(&que_errors, "QUERIES lines=%d valid=%d errors=%zu", query_lines, query_count,
         query_errors.count);
    lines_take(&que_errors, query_errors);
    int order[400];
    for (int i = 0; i < cause_count; ++i)
        order[i] = i;
    for (int i = 1; i < cause_count; ++i) {
        int current = order[i], j = i;
        while (j) {
            Cause a = causes[current], b = causes[order[j - 1]];
            bool less = a.count != b.count ? a.count > b.count : strcmp(a.name, b.name) < 0;
            if (!less)
                break;
            order[j] = order[j - 1];
            --j;
        }
        order[j] = current;
    }
    line(&cause_lines, "CAUSES kinds=%d", cause_count);
    for (int i = 0; i < cause_count; ++i)
        line(&cause_lines, "%s=%d", causes[order[i]].name, causes[order[i]].count);
    Paragraphs errors = {0};
    paragraph_add(&errors, mol_errors);
    paragraph_add(&errors, que_errors);
    paragraph_add(&errors, cause_lines);
    if (mkdir("output", 0777) != 0 && errno != EEXIST) {
        perror("output");
        exit(EXIT_FAILURE);
    }
    write_lines("properties.csv", &property_lines);
    save_paragraphs("canonical.txt", canonical_paragraphs(molecules, molecule_count));
    save_paragraphs("rings.txt", ring_paragraphs(molecules, molecule_count, &elements));
    save_paragraphs("substructure.txt",
                    substructure_paragraphs(queries, query_count, molecules, molecule_count));
    save_paragraphs("similarity.txt",
                    similarity_paragraphs(queries, query_count, molecules, molecule_count));
    save_paragraphs("errors.txt", errors);
    lines_free(&property_lines);
    for (int i = 0; i < query_count; ++i) {
        molecule_free(queries[i]->pattern);
        words_free(&queries[i]->source);
        free(queries[i]);
    }
    for (int i = 0; i < molecule_count; ++i)
        molecule_free(molecules[i]);
    for (int i = 0; i < cause_count; ++i)
        free(causes[i].name);
    return EXIT_SUCCESS;
}

#include "chemistry.h"
#include <stdlib.h>
#include <string.h>
void ints_add(IntList *list, int value) {
    if (list->count == list->capacity) {
        list->capacity = list->capacity ? 2 * list->capacity : 8;
        list->items = resize(list->items, (size_t)list->capacity * sizeof(int));
    }
    list->items[list->count++] = value;
}
IntList ints_copy(const IntList *list) {
    IntList out = {0};
    if (list->count) {
        out.count = out.capacity = list->count;
        out.items = allocate((size_t)list->count * sizeof(int));
        memcpy(out.items, list->items, (size_t)list->count * sizeof(int));
    }
    return out;
}
void ints_free(IntList *list) {
    free(list->items);
    *list = (IntList){0};
}
static int int_compare(const void *left, const void *right) {
    int a = *(const int *)left, b = *(const int *)right;
    return (a > b) - (a < b);
}
void ints_sort(IntList *list) {
    if (list->count)
        qsort(list->items, (size_t)list->count, sizeof(int), int_compare);
}
bool ints_contains(const IntList *list, int value) {
    for (int i = 0; i < list->count; ++i)
        if (list->items[i] == value)
            return true;
    return false;
}
int element_index(const Elements *elements, const char *symbol) {
    for (int i = 0; i < elements->count; ++i)
        if (strcmp(elements->items[i].symbol, symbol) == 0)
            return i;
    return -1;
}
void read_elements(Elements *elements) {
    *elements = (Elements){0};
    Lines source = read_lines("input/elements.txt");
    for (size_t i = 0; i < source.count; ++i) {
        if (ignored(source.items[i]))
            continue;
        Words a = split(source.items[i], ' '), valences = split(a.items[3], ',');
        Element *element = &elements->items[elements->count++];
        strcpy(element->symbol, a.items[0]);
        element->number = atoi(a.items[1]);
        element->weight = atoi(a.items[2]);
        for (size_t j = 0; j < valences.count; ++j)
            element->valences[element->valence_count++] = atoi(valences.items[j]);
        words_free(&a);
        words_free(&valences);
    }
    lines_free(&source);
}
int bond_other(const Bond *bond, int atom) { return atom == bond->a ? bond->b : bond->a; }
Molecule *molecule_new(void) {
    Molecule *m = allocate(sizeof(*m));
    memset(m, 0, sizeof(*m));
    return m;
}
void molecule_add_atom(Molecule *m, Atom atom) {
    if (m->atom_count == m->atom_capacity) {
        m->atom_capacity = m->atom_capacity ? 2 * m->atom_capacity : 16;
        m->atoms = resize(m->atoms, (size_t)m->atom_capacity * sizeof(Atom));
    }
    m->atoms[m->atom_count++] = atom;
}
void molecule_add_bond(Molecule *m, Bond bond) {
    if (m->bond_count == m->bond_capacity) {
        m->bond_capacity = m->bond_capacity ? 2 * m->bond_capacity : 16;
        m->bonds = resize(m->bonds, (size_t)m->bond_capacity * sizeof(Bond));
    }
    m->bonds[m->bond_count++] = bond;
}
static int bond_compare(const void *left, const void *right) {
    const Bond *a = left, *b = right;
    return a->a != b->a ? (a->a > b->a) - (a->a < b->a) : (a->b > b->b) - (a->b < b->b);
}
void molecule_build(Molecule *m) {
    if (m->bond_count)
        qsort(m->bonds, (size_t)m->bond_count, sizeof(Bond), bond_compare);
    m->adjacent = allocate((size_t)m->atom_count * sizeof(IntList));
    memset(m->adjacent, 0, (size_t)m->atom_count * sizeof(IntList));
    for (int e = 0; e < m->bond_count; ++e) {
        ints_add(&m->adjacent[m->bonds[e].a], e);
        ints_add(&m->adjacent[m->bonds[e].b], e);
    }
    for (int a = 0; a < m->atom_count; ++a) {
        IntList *list = &m->adjacent[a];
        for (int i = 1; i < list->count; ++i) {
            int edge = list->items[i], j = i;
            while (j &&
                   bond_other(&m->bonds[list->items[j - 1]], a) > bond_other(&m->bonds[edge], a)) {
                list->items[j] = list->items[j - 1];
                --j;
            }
            list->items[j] = edge;
        }
    }
}
const Bond *molecule_bond(const Molecule *m, int a, int b) {
    for (int i = 0; i < m->adjacent[a].count; ++i) {
        const Bond *bond = &m->bonds[m->adjacent[a].items[i]];
        if (bond_other(bond, a) == b)
            return bond;
    }
    return NULL;
}
int atom_base(const Molecule *m, int atom) {
    int sum = 0;
    for (int i = 0; i < m->adjacent[atom].count; ++i) {
        int type = m->bonds[m->adjacent[atom].items[i]].type;
        sum += type == 4 ? 1 : type;
    }
    return sum;
}
int atom_multiplicity(const Molecule *m, int atom) {
    int sum = 0;
    for (int i = 0; i < m->adjacent[atom].count; ++i)
        sum += m->bonds[m->adjacent[atom].items[i]].multiplicity;
    return sum;
}
bool needs_pi(const Molecule *m, int atom, const Elements *elements, bool hydrogens) {
    const Atom *a = &m->atoms[atom];
    return a->aromatic && elements->items[a->element].valences[0] + a->charge >=
                              atom_base(m, atom) + (hydrogens ? a->hydrogens : 0) + 1;
}
bool organic_hydrogens(const Molecule *m, int atom, const Elements *elements, int *out) {
    int total = atom_multiplicity(m, atom);
    const Element *e = &elements->items[m->atoms[atom].element];
    for (int i = 0; i < e->valence_count; ++i)
        if (e->valences[i] >= total) {
            *out = e->valences[i] - total;
            return true;
        }
    return false;
}
void molecule_free(Molecule *m) {
    if (!m)
        return;
    for (int i = 0; i < m->atom_count; ++i) {
        free(m->atoms[i].choices);
        if (m->adjacent)
            ints_free(&m->adjacent[i]);
    }
    for (int i = 0; i < m->ring_count; ++i)
        ints_free(&m->rings[i]);
    free(m->name);
    free(m->atoms);
    free(m->bonds);
    free(m->adjacent);
    free(m->rings);
    free(m->ring_atoms);
    free(m->ranks);
    free(m->canonical);
    free(m->scaffold);
    free(m->formula);
    free(m);
}

#include "chemistry.h"
#include <stdlib.h>
#include <string.h>
typedef struct {
    uint64_t words[5];
} BondSet;
typedef struct {
    IntList atoms;
    BondSet bonds;
    int ordinal;
} Candidate;
typedef struct {
    bool occupied;
    BondSet key;
} SetSlot;
typedef struct {
    SetSlot *items;
    size_t count, capacity;
} BondSets;
static uint64_t set_hash(BondSet key) {
    uint64_t hash = UINT64_C(14695981039346656037);
    for (int i = 0; i < 5; ++i) {
        hash ^= key.words[i];
        hash *= UINT64_C(1099511628211);
    }
    return hash;
}
static void set_grow(BondSets *sets) {
    size_t old_capacity = sets->capacity;
    SetSlot *old = sets->items;
    sets->capacity = old_capacity ? 2 * old_capacity : 256;
    sets->items = allocate(sets->capacity * sizeof(SetSlot));
    memset(sets->items, 0, sets->capacity * sizeof(SetSlot));
    for (size_t i = 0; i < old_capacity; ++i)
        if (old[i].occupied) {
            size_t at = (size_t)set_hash(old[i].key) & (sets->capacity - 1);
            while (sets->items[at].occupied)
                at = (at + 1) & (sets->capacity - 1);
            sets->items[at] = old[i];
        }
    free(old);
}
static bool set_insert(BondSets *sets, BondSet key) {
    if (!sets->capacity || 2 * (sets->count + 1) > sets->capacity)
        set_grow(sets);
    size_t at = (size_t)set_hash(key) & (sets->capacity - 1);
    while (sets->items[at].occupied) {
        if (memcmp(&sets->items[at].key, &key, sizeof(key)) == 0)
            return false;
        at = (at + 1) & (sets->capacity - 1);
    }
    sets->items[at] = (SetSlot){true, key};
    ++sets->count;
    return true;
}
static IntList path_to(const int *parent, int atom) {
    IntList result = {0};
    for (; atom >= 0; atom = parent[atom])
        ints_add(&result, atom);
    return result;
}
static IntList canonical_ring(const IntList *ring) {
    int first = 0, n = ring->count;
    for (int i = 1; i < n; ++i)
        if (ring->items[i] < ring->items[first])
            first = i;
    int direction = ring->items[(first + 1) % n] < ring->items[(first + n - 1) % n] ? 1 : -1;
    IntList result = {0};
    for (int i = 0; i < n; ++i)
        ints_add(&result, ring->items[(first + direction * i + n) % n]);
    return result;
}
static int candidate_compare(const void *left, const void *right) {
    const Candidate *a = left, *b = right;
    return a->atoms.count != b->atoms.count
               ? (a->atoms.count > b->atoms.count) - (a->atoms.count < b->atoms.count)
               : (a->ordinal > b->ordinal) - (a->ordinal < b->ordinal);
}
static int ring_compare(const void *left, const void *right) {
    const IntList *a = left, *b = right;
    if (a->count != b->count)
        return (a->count > b->count) - (a->count < b->count);
    for (int i = 0; i < a->count; ++i)
        if (a->items[i] != b->items[i])
            return a->items[i] < b->items[i] ? -1 : 1;
    return 0;
}
static bool set_nonempty(BondSet set) {
    for (int i = 0; i < 5; ++i)
        if (set.words[i])
            return true;
    return false;
}
void detect_rings(Molecule *m) {
    int n = m->atom_count;
    Candidate *candidates = NULL;
    size_t count = 0, capacity = 0;
    BondSets seen = {0};
    int *parent = allocate((size_t)n * sizeof(int)), *queue = allocate((size_t)n * sizeof(int));
    int *bond_index = allocate((size_t)n * n * sizeof(int));
    for (int i = 0; i < n * n; ++i)
        bond_index[i] = -1;
    for (int e = 0; e < m->bond_count; ++e) {
        Bond b = m->bonds[e];
        bond_index[b.a * n + b.b] = bond_index[b.b * n + b.a] = e;
    }
    for (int root = 0; root < n; ++root) {
        for (int i = 0; i < n; ++i)
            parent[i] = -2;
        parent[root] = -1;
        queue[0] = root;
        int tail = 1;
        for (int head = 0; head < tail; ++head) {
            int a = queue[head];
            for (int i = 0; i < m->adjacent[a].count; ++i) {
                int next = bond_other(&m->bonds[m->adjacent[a].items[i]], a);
                if (parent[next] == -2) {
                    parent[next] = a;
                    queue[tail++] = next;
                }
            }
        }
        for (int e = 0; e < m->bond_count; ++e) {
            Bond bond = m->bonds[e];
            if (parent[bond.a] == bond.b || parent[bond.b] == bond.a)
                continue;
            IntList px = path_to(parent, bond.a), py = path_to(parent, bond.b);
            bool overlap = false;
            for (int i = 0; i + 1 < px.count; ++i)
                for (int j = 0; j + 1 < py.count; ++j)
                    if (px.items[i] == py.items[j])
                        overlap = true;
            if (overlap) {
                ints_free(&px);
                ints_free(&py);
                continue;
            }
            IntList atoms = {0};
            for (int i = px.count - 1; i >= 0; --i)
                ints_add(&atoms, px.items[i]);
            for (int i = 0; i + 1 < py.count; ++i)
                ints_add(&atoms, py.items[i]);
            ints_free(&px);
            ints_free(&py);
            BondSet vector = {{0}};
            for (int i = 0; i < atoms.count; ++i) {
                int bit = bond_index[atoms.items[i] * n + atoms.items[(i + 1) % atoms.count]];
                vector.words[bit / 64] |= UINT64_C(1) << (bit % 64);
            }
            if (set_insert(&seen, vector)) {
                if (count == capacity) {
                    capacity = capacity ? 2 * capacity : 64;
                    candidates = resize(candidates, capacity * sizeof(Candidate));
                }
                candidates[count] = (Candidate){atoms, vector, (int)count};
                ++count;
            } else
                ints_free(&atoms);
        }
    }
    if (count)
        qsort(candidates, count, sizeof(Candidate), candidate_compare);
    BondSet basis[300];
    bool present[300] = {0};
    m->ring_atoms = allocate((size_t)n * sizeof(bool));
    memset(m->ring_atoms, 0, (size_t)n * sizeof(bool));
    for (size_t i = 0; i < count; ++i) {
        Candidate *c = &candidates[i];
        BondSet reduced = c->bonds;
        while (set_nonempty(reduced)) {
            int pivot = m->bond_count - 1;
            while (!(reduced.words[pivot / 64] & (UINT64_C(1) << (pivot % 64))))
                --pivot;
            if (present[pivot])
                for (int j = 0; j < 5; ++j)
                    reduced.words[j] ^= basis[pivot].words[j];
            else {
                basis[pivot] = reduced;
                present[pivot] = true;
                if (m->ring_count == m->ring_capacity) {
                    m->ring_capacity = m->ring_capacity ? 2 * m->ring_capacity : 8;
                    m->rings = resize(m->rings, (size_t)m->ring_capacity * sizeof(IntList));
                }
                m->rings[m->ring_count++] = canonical_ring(&c->atoms);
                for (int j = 0; j < c->atoms.count; ++j)
                    m->ring_atoms[c->atoms.items[j]] = true;
                for (int e = 0; e < m->bond_count; ++e)
                    if (c->bonds.words[e / 64] & (UINT64_C(1) << (e % 64)))
                        m->bonds[e].ring = true;
                break;
            }
        }
        ints_free(&c->atoms);
    }
    if (m->ring_count)
        qsort(m->rings, (size_t)m->ring_count, sizeof(IntList), ring_compare);
    free(candidates);
    free(seen.items);
    free(parent);
    free(queue);
    free(bond_index);
}
typedef struct {
    Molecule *m;
    const IntList *system;
    bool *member;
    int *paired;
} Matching;
static bool match(Matching *s) {
    int u = -1;
    for (int i = 0; i < s->system->count; ++i)
        if (s->paired[s->system->items[i]] < 0) {
            u = s->system->items[i];
            break;
        }
    if (u < 0)
        return true;
    for (int i = 0; i < s->m->adjacent[u].count; ++i) {
        Bond *bond = &s->m->bonds[s->m->adjacent[u].items[i]];
        int v = bond_other(bond, u);
        if (bond->type != 4 || !s->member[v] || s->paired[v] >= 0)
            continue;
        s->paired[u] = v;
        s->paired[v] = u;
        if (match(s))
            return true;
        s->paired[u] = s->paired[v] = -1;
    }
    return false;
}
bool kekulize(Molecule *m, const Elements *elements, ParseError *error) {
    int n = m->atom_count;
    bool *need = allocate((size_t)n * sizeof(bool)), *seen = allocate((size_t)n * sizeof(bool)),
         *member = allocate((size_t)n * sizeof(bool));
    int *paired = allocate((size_t)n * sizeof(int));
    memset(seen, 0, (size_t)n * sizeof(bool));
    for (int i = 0; i < n; ++i) {
        need[i] = needs_pi(m, i, elements, true);
        paired[i] = -1;
    }
    bool success = true;
    for (int first = 0; first < n; ++first) {
        if (!need[first] || seen[first])
            continue;
        IntList system = {0};
        ints_add(&system, first);
        seen[first] = true;
        for (int head = 0; head < system.count; ++head) {
            int u = system.items[head];
            for (int j = 0; j < m->adjacent[u].count; ++j) {
                Bond *bond = &m->bonds[m->adjacent[u].items[j]];
                int v = bond_other(bond, u);
                if (bond->type == 4 && need[v] && !seen[v]) {
                    seen[v] = true;
                    ints_add(&system, v);
                }
            }
        }
        ints_sort(&system);
        memset(member, 0, (size_t)n * sizeof(bool));
        for (int i = 0; i < system.count; ++i)
            member[system.items[i]] = true;
        Matching matching = {m, &system, member, paired};
        if (!match(&matching)) {
            *error = (ParseError){"kekulization failed", m->atoms[first].column};
            success = false;
            ints_free(&system);
            break;
        }
        ints_free(&system);
    }
    if (success)
        for (int e = 0; e < m->bond_count; ++e) {
            Bond *b = &m->bonds[e];
            b->multiplicity = b->type == 4 ? (paired[b->a] == b->b ? 2 : 1) : b->type;
        }
    free(need);
    free(seen);
    free(member);
    free(paired);
    return success;
}

#include "chemistry.h"
#include <stdlib.h>
#include <string.h>

const char *pattern_atom(const char *source, size_t at, const Elements *elements, Atom *atom,
                         size_t *next) {
    *atom = (Atom){0};
    char c = source[at];
    if (c == '*' || c == 'A' || c == 'a') {
        atom->wildcard = c;
        *next = at + 1;
        return NULL;
    }
    if (c == '[') {
        const char *end = strchr(source + at + 1, ']');
        if (!end)
            return "unclosed bracket";
        size_t size = (size_t)(end - (source + at + 1));
        char *content = allocate(size + 1);
        memcpy(content, source + at + 1, size);
        content[size] = 0;
        Words parts = split(content, ',');
        free(content);
        for (size_t i = 0; i < parts.count; ++i) {
            Atom choice;
            size_t finish;
            if (!*parts.items[i] || !organic_atom(parts.items[i], 0, elements, &choice, &finish) ||
                finish != strlen(parts.items[i])) {
                words_free(&parts);
                return "bad bracket atom";
            }
            atom->choices =
                resize(atom->choices, (size_t)(atom->choice_count + 1) * sizeof(Choice));
            atom->choices[atom->choice_count++] = (Choice){choice.element, choice.aromatic};
        }
        words_free(&parts);
        *next = (size_t)(end - source) + 1;
        return NULL;
    }
    if (!organic_atom(source, at, elements, atom, next))
        return "unexpected character";
    atom->choices = allocate(sizeof(Choice));
    atom->choices[0] = (Choice){atom->element, atom->aromatic};
    atom->choice_count = 1;
    return NULL;
}
static bool atom_matches(const Atom *pattern, const Atom *atom) {
    if (pattern->wildcard == '*')
        return true;
    if (pattern->wildcard == 'A')
        return !atom->aromatic;
    if (pattern->wildcard == 'a')
        return atom->aromatic;
    for (int i = 0; i < pattern->choice_count; ++i)
        if (pattern->choices[i].element == atom->element &&
            pattern->choices[i].aromatic == atom->aromatic)
            return true;
    return false;
}
Molecule *molecule_pattern(const Molecule *m) {
    Molecule *pattern = molecule_new();
    for (int i = 0; i < m->atom_count; ++i) {
        Atom atom = {.choice_count = 1, .choices = allocate(sizeof(Choice))};
        atom.choices[0] = (Choice){m->atoms[i].element, m->atoms[i].aromatic};
        molecule_add_atom(pattern, atom);
    }
    for (int e = 0; e < m->bond_count; ++e) {
        Bond b = m->bonds[e];
        molecule_add_bond(pattern, (Bond){.a = b.a, .b = b.b, .match = 1 << b.type});
    }
    molecule_build(pattern);
    return pattern;
}
typedef struct {
    uint64_t words[2];
} AtomSet;
typedef struct {
    const Molecule *pattern, *molecule;
    int *mapping;
    bool *used;
    Embeddings result;
    AtomSet *sets;
    size_t count, capacity;
} Search;
static void search(Search *s, int index) {
    if (index == s->pattern->atom_count) {
        ++s->result.count;
        if (!s->result.first.count)
            for (int i = 0; i < s->pattern->atom_count; ++i)
                ints_add(&s->result.first, s->mapping[i] + 1);
        AtomSet set = {{0}};
        for (int i = 0; i < s->pattern->atom_count; ++i)
            set.words[s->mapping[i] / 64] |= UINT64_C(1) << (s->mapping[i] % 64);
        if (s->count == s->capacity) {
            s->capacity = s->capacity ? 2 * s->capacity : 64;
            s->sets = resize(s->sets, s->capacity * sizeof(AtomSet));
        }
        s->sets[s->count++] = set;
        return;
    }
    for (int candidate = 0; candidate < s->molecule->atom_count; ++candidate) {
        if (s->used[candidate] ||
            !atom_matches(&s->pattern->atoms[index], &s->molecule->atoms[candidate]))
            continue;
        bool valid = true;
        for (int i = 0; i < s->pattern->adjacent[index].count; ++i) {
            const Bond *bond = &s->pattern->bonds[s->pattern->adjacent[index].items[i]];
            int other = bond_other(bond, index);
            if (other >= index)
                continue;
            const Bond *actual = molecule_bond(s->molecule, candidate, s->mapping[other]);
            if (!actual || !(bond->match & (1 << actual->type))) {
                valid = false;
                break;
            }
        }
        if (valid) {
            s->mapping[index] = candidate;
            s->used[candidate] = true;
            search(s, index + 1);
            s->used[candidate] = false;
            s->mapping[index] = -1;
        }
    }
}
static int set_compare(const void *left, const void *right) {
    const AtomSet *a = left, *b = right;
    for (int i = 0; i < 2; ++i)
        if (a->words[i] != b->words[i])
            return a->words[i] < b->words[i] ? -1 : 1;
    return 0;
}
Embeddings embeddings(const Molecule *pattern, const Molecule *molecule) {
    if (pattern->atom_count > molecule->atom_count)
        return (Embeddings){0};
    Search s = {.pattern = pattern, .molecule = molecule};
    s.mapping = allocate((size_t)pattern->atom_count * sizeof(int));
    for (int i = 0; i < pattern->atom_count; ++i)
        s.mapping[i] = -1;
    s.used = allocate((size_t)molecule->atom_count * sizeof(bool));
    memset(s.used, 0, (size_t)molecule->atom_count * sizeof(bool));
    search(&s, 0);
    if (s.count)
        qsort(s.sets, s.count, sizeof(AtomSet), set_compare);
    for (size_t i = 0; i < s.count; ++i)
        if (!i || set_compare(&s.sets[i - 1], &s.sets[i]))
            ++s.result.unique;
    free(s.mapping);
    free(s.used);
    free(s.sets);
    return s.result;
}
typedef struct {
    Molecule *m;
    int *codes;
    bool *visited;
} Fingerprint;
static void path_visit(Fingerprint *s, int atom, int depth, int hash) {
    ++s->m->paths;
    s->m->bits[(hash % 1024) / 64] |= UINT64_C(1) << ((hash % 1024) % 64);
    if (depth == 5)
        return;
    for (int i = 0; i < s->m->adjacent[atom].count; ++i) {
        Bond bond = s->m->bonds[s->m->adjacent[atom].items[i]];
        int next = bond_other(&bond, atom);
        if (s->visited[next])
            continue;
        int value = (hash * 31 + bond.type) % 1000003;
        value = (value * 31 + s->codes[next]) % 1000003;
        s->visited[next] = true;
        path_visit(s, next, depth + 1, value);
        s->visited[next] = false;
    }
}
static int bit_count(uint64_t value) {
    int count = 0;
    while (value) {
        value &= value - 1;
        ++count;
    }
    return count;
}
void fingerprint(Molecule *m, const Elements *elements) {
    Fingerprint s = {.m = m,
                     .codes = allocate((size_t)m->atom_count * sizeof(int)),
                     .visited = allocate((size_t)m->atom_count * sizeof(bool))};
    memset(s.visited, 0, (size_t)m->atom_count * sizeof(bool));
    for (int i = 0; i < m->atom_count; ++i)
        s.codes[i] = 16 * elements->items[m->atoms[i].element].number +
                     (m->atoms[i].aromatic ? 8 : 0) + m->adjacent[i].count;
    for (int i = 0; i < m->atom_count; ++i) {
        s.visited[i] = true;
        path_visit(&s, i, 0, s.codes[i]);
        s.visited[i] = false;
    }
    for (int i = 0; i < 16; ++i)
        m->bit_count += bit_count(m->bits[i]);
    free(s.codes);
    free(s.visited);
}
Fraction fraction(int n, int d) {
    int a = n, b = d;
    while (b) {
        int remainder = a % b;
        a = b;
        b = remainder;
    }
    return (Fraction){n / a, d / a};
}
int fraction_compare(Fraction a, Fraction b) {
    int left = a.n * b.d, right = b.n * a.d;
    return (left > right) - (left < right);
}
char *fraction_text(Fraction f, char out[32]) {
    snprintf(out, 32, "%d/%d", f.n, f.d);
    return out;
}
Similarity similarity(const Molecule *a, const Molecule *b) {
    int common = 0, total = 0;
    for (int i = 0; i < 16; ++i) {
        common += bit_count(a->bits[i] & b->bits[i]);
        total += bit_count(a->bits[i] | b->bits[i]);
    }
    return (Similarity){fraction(common, total), common, total};
}

#include "chemistry.h"
#include <stdlib.h>
#include <string.h>
bool digit(char c) { return c >= '0' && c <= '9'; }
bool organic_atom(const char *source, size_t at, const Elements *elements, Atom *atom,
                  size_t *next) {
    *atom = (Atom){0};
    char symbol[3] = {source[at], 0, 0};
    if (source[at + 1] && ((source[at] == 'C' && source[at + 1] == 'l') ||
                           (source[at] == 'B' && source[at + 1] == 'r'))) {
        symbol[1] = source[at + 1];
        *next = at + 2;
    } else if (strchr("BCNOPSFI", source[at]))
        *next = at + 1;
    else if (strchr("bcnops", source[at])) {
        symbol[0] = (char)(source[at] - 'a' + 'A');
        atom->aromatic = true;
        *next = at + 1;
    } else
        return false;
    atom->element = element_index(elements, symbol);
    return true;
}
const char *bracket_atom(const char *content, const Elements *elements, Atom *atom) {
    *atom = (Atom){.bracket = true};
    size_t i = 0;
    while (digit(content[i]))
        ++i;
    if (i >= 4 || (i && content[0] == '0'))
        return "bad bracket atom";
    if (i)
        atom->mass = atoi(content);
    if (!content[i])
        return "bad bracket atom";
    char c = content[i], symbol[3] = {c, 0, 0};
    if (strchr("bcnops", c)) {
        symbol[0] = (char)(c - 'a' + 'A');
        atom->aromatic = true;
        ++i;
        atom->element = element_index(elements, symbol);
    } else if (c >= 'A' && c <= 'Z') {
        if (content[i + 1] >= 'a' && content[i + 1] <= 'z')
            symbol[1] = content[i + 1];
        int element = element_index(elements, symbol);
        if (symbol[1] && element >= 0) {
            atom->element = element;
            i += 2;
        } else {
            symbol[1] = 0;
            element = element_index(elements, symbol);
            if (element < 0)
                return "unknown element";
            atom->element = element;
            ++i;
        }
    } else
        return "bad bracket atom";
    if (content[i] == '@') {
        ++i;
        if (content[i] == '@')
            ++i;
    }
    if (content[i] == 'H') {
        atom->hydrogens = 1;
        ++i;
        if (digit(content[i]))
            atom->hydrogens = content[i++] - '0';
    }
    if (content[i] == '+' || content[i] == '-') {
        int sign = content[i++] == '+' ? 1 : -1, magnitude = 1;
        if (content[i] >= '1' && content[i] <= '9')
            magnitude = content[i++] - '0';
        atom->charge = sign * magnitude;
    }
    return content[i] ? "bad bracket atom" : NULL;
}
int symbol_type(char c) {
    if (c == '-' || c == '/' || c == '\\')
        return 1;
    if (c == '=')
        return 2;
    if (c == '#')
        return 3;
    if (c == ':')
        return 4;
    if (c == '~')
        return 5;
    return 0;
}
static void add_bond(Molecule *m, int a, int b, char symbol, bool pattern) {
    if (a > b) {
        int t = a;
        a = b;
        b = t;
    }
    Bond bond = {.a = a, .b = b, .symbol = symbol};
    if (pattern) {
        int kind = symbol_type(symbol);
        bond.match = kind == 0   ? (1 << 1) | (1 << 4)
                     : kind == 5 ? (1 << 1) | (1 << 2) | (1 << 3) | (1 << 4)
                                 : 1 << kind;
    }
    molecule_add_bond(m, bond);
}
Molecule *parse_smiles(const char *source, const Elements *elements, bool pattern,
                       ParseError *error) {
    typedef struct {
        int atom, column;
        char symbol;
        bool active;
    } Open;
    typedef struct {
        int atom, column;
    } Branch;
    Molecule *m = molecule_new();
    int current = -1, pending_column = 0, stack_count = 0;
    char pending = 0;
    size_t length = strlen(source);
    Branch *stack = allocate((length + 1) * sizeof(Branch));
    Open open[100] = {{0}};
    *error = (ParseError){0};
    for (size_t i = 0; i < length;) {
        char c = source[i];
        int column = (int)i + 1;
        const char *symbols = pattern ? "-=#:~" : "-/\\=#:";
        if (strchr(symbols, c)) {
            if (current < 0 || pending) {
                *error = (ParseError){"misplaced bond", column};
                goto fail;
            }
            pending = c;
            pending_column = column;
            ++i;
        } else if (c == '(') {
            if (current < 0 || pending || (i && source[i - 1] == '(')) {
                *error = (ParseError){"misplaced branch", column};
                goto fail;
            }
            stack[stack_count++] = (Branch){current, column};
            ++i;
        } else if (c == ')') {
            if (!stack_count) {
                *error = (ParseError){"unmatched parenthesis", column};
                goto fail;
            }
            if (pending) {
                *error = (ParseError){"dangling bond", pending_column};
                goto fail;
            }
            if (i && source[i - 1] == '(') {
                *error = (ParseError){"empty branch", column};
                goto fail;
            }
            current = stack[--stack_count].atom;
            ++i;
        } else if (digit(c) || c == '%') {
            if (current < 0) {
                *error = (ParseError){"misplaced ring closure", column};
                goto fail;
            }
            int number;
            if (c == '%') {
                if (i + 2 >= length || !digit(source[i + 1]) || !digit(source[i + 2])) {
                    *error = (ParseError){"bad ring number", column};
                    goto fail;
                }
                number = 10 * (source[i + 1] - '0') + source[i + 2] - '0';
                i += 3;
            } else {
                number = c - '0';
                ++i;
            }
            char symbol = pending;
            pending = 0;
            if (!open[number].active)
                open[number] = (Open){current, column, symbol, true};
            else {
                Open old = open[number];
                if (old.atom == current) {
                    *error = (ParseError){"self bond", column};
                    goto fail;
                }
                if (old.symbol && symbol &&
                    (pattern ? old.symbol != symbol
                             : symbol_type(old.symbol) != symbol_type(symbol))) {
                    *error = (ParseError){"ring bond mismatch", column};
                    goto fail;
                }
                for (int e = 0; e < m->bond_count; ++e)
                    if ((m->bonds[e].a == old.atom && m->bonds[e].b == current) ||
                        (m->bonds[e].a == current && m->bonds[e].b == old.atom)) {
                        *error = (ParseError){"duplicate bond", column};
                        goto fail;
                    }
                add_bond(m, old.atom, current, symbol ? symbol : old.symbol, pattern);
                open[number].active = false;
            }
        } else {
            Atom atom = {0};
            size_t next = i;
            const char *reason = NULL;
            if (pattern)
                reason = pattern_atom(source, i, elements, &atom, &next);
            else if (c == '[') {
                const char *end = strchr(source + i + 1, ']');
                if (!end) {
                    *error = (ParseError){"unclosed bracket", column};
                    goto fail;
                }
                size_t size = (size_t)(end - (source + i + 1));
                char *content = allocate(size + 1);
                memcpy(content, source + i + 1, size);
                content[size] = 0;
                reason = bracket_atom(content, elements, &atom);
                free(content);
                next = (size_t)(end - source) + 1;
            } else if (!organic_atom(source, i, elements, &atom, &next))
                reason = "unexpected character";
            if (reason) {
                free(atom.choices);
                *error = (ParseError){reason, column};
                goto fail;
            }
            atom.column = column;
            molecule_add_atom(m, atom);
            int index = m->atom_count - 1;
            if (current >= 0)
                add_bond(m, current, index, pending, pattern);
            current = index;
            pending = 0;
            i = next;
        }
    }
    if (pending) {
        *error = (ParseError){"dangling bond", pending_column};
        goto fail;
    }
    if (stack_count) {
        *error = (ParseError){"unmatched parenthesis", stack[0].column};
        goto fail;
    }
    int earliest = (int)length + 1;
    for (int i = 0; i < 100; ++i)
        if (open[i].active && open[i].column < earliest)
            earliest = open[i].column;
    if (earliest <= (int)length) {
        *error = (ParseError){"unclosed ring", earliest};
        goto fail;
    }
    free(stack);
    molecule_build(m);
    return m;
fail:
    free(stack);
    molecule_free(m);
    return NULL;
}
